/// Унікальні жанри, відсортовані за алфавітом.
final List<String> allGenres = ({for (final b in allBooks) b.genre}.toList()..sort());

/// Пошук за параметром шляху `:bookId`. Невалідний або невідомий id → `null`.
Book? findBookById(String? id) {
  final number = int.tryParse(id ?? '');
  if (number == null) return null;
  for (final book in allBooks) {
    if (book.id == number) return book;
  }
  return null;
}

/// Каталог за жанром; `null` або невідомий жанр → усі книги.
List<Book> booksByGenre(String? genre) {
  if (genre == null || !allGenres.contains(genre)) return allBooks;
  return allBooks.where((b) => b.genre == genre).toList();
}
